import sys

def main():
    data = sys.stdin.read().split()
    n, K = int(data[0]), int(data[1])
    a = list(map(int, data[2:2 + n]))
    b = list(map(int, data[2 + n:2 + 2 * n]))
    INF = float('inf')
    prev = [INF] * n
    prev[0] = 0
    best = INF
    for _ in range(min(K, n - 1)):
        cur = [INF] * n
        ms, cs = [], []
        h = 0
        for j in range(1, n):
            i = j - 1
            if prev[i] < INF:
                m = -2 * a[i]
                c = prev[i] + a[i] * a[i]
                if ms and ms[-1] == m:
                    if cs[-1] <= c:
                        m = None
                    else:
                        ms.pop(); cs.pop()
                if m is not None:
                    while len(ms) - h >= 2 and (c - cs[-2]) * (ms[-2] - ms[-1]) <= (cs[-1] - cs[-2]) * (ms[-2] - m):
                        ms.pop(); cs.pop()
                    ms.append(m); cs.append(c)
            if len(ms) > h:
                x = a[j]
                while len(ms) - h >= 2 and ms[h + 1] * x + cs[h + 1] <= ms[h] * x + cs[h]:
                    h += 1
                cur[j] = ms[h] * x + cs[h] + x * x + b[j]
        prev = cur
        if prev[n - 1] < best:
            best = prev[n - 1]
    print(best)

